import {COUNTRIES} from './data.js?v=173';
import {esc} from './ui.js?v=173';
export function cityArt(id,extra=''){const i=COUNTRIES.findIndex(c=>c.id===id),c=COUNTRIES[i];return `<div class="city-art ${extra}" role="img" aria-label="${c.city}, illustration de 2040" style="--cx:${i%3*50}%;--cy:${Math.floor(i/3)*100/3}%"><div class="city-caption"><strong>${c.city}</strong><span>2040 / ${c.id}</span></div></div>`;}
export function fullBody(agent){const a={...agent,id:agent.templateId||agent.id};if(a.id==='p25')return `<svg class="full-body iris-body" viewBox="200 0 650 1536" role="img" aria-label="${esc(a.name)}, personnage debout" preserveAspectRatio="xMidYMid meet"><image href="./assets/alba-full.png" width="1024" height="1536"/></svg>`;if(a.id==='p26')return `<svg class="full-body iris-body" viewBox="200 0 650 1536" role="img" aria-label="${esc(a.name)}, personnage debout" preserveAspectRatio="xMidYMid meet"><image href="./assets/raven-full.png?v=173" width="1024" height="1536"/></svg>`;if(a.id==='p23')return `<svg class="full-body iris-body" viewBox="200 0 650 1536" role="img" aria-label="${esc(a.name)}, personnage debout" preserveAspectRatio="xMidYMid meet"><image href="./assets/selin-full.png" width="1024" height="1536"/></svg>`;if(a.id==='p24')return `<svg class="full-body iris-body" viewBox="200 0 650 1536" role="img" aria-label="${esc(a.name)}, personnage debout" preserveAspectRatio="xMidYMid meet"><image href="./assets/rocket-full.png" width="1024" height="1536"/></svg>`;if(a.id==='p22')return `<svg class="full-body iris-body" viewBox="200 0 650 1536" role="img" aria-label="${esc(a.name)}, personnage debout" preserveAspectRatio="xMidYMid meet"><image href="./assets/dante-full.png" width="1024" height="1536"/></svg>`;if(a.id==='p21')return `<svg class="full-body iris-body" viewBox="200 0 650 1536" role="img" aria-label="${esc(a.name)}, personnage debout" preserveAspectRatio="xMidYMid meet"><image href="./assets/adler-full.png" width="1024" height="1536"/></svg>`;if(a.id==='p20')return `<svg class="full-body iris-body" viewBox="200 0 650 1536" role="img" aria-label="${esc(a.name)}, personnage debout" preserveAspectRatio="xMidYMid meet"><image href="./assets/nox-full.png" width="1024" height="1536"/></svg>`;if(a.id==='p19')return `<svg class="full-body iris-body" viewBox="200 0 650 1536" role="img" aria-label="${esc(a.name)}, personnage debout" preserveAspectRatio="xMidYMid meet"><image href="./assets/marlowe-full.png" width="1024" height="1536"/></svg>`;if(a.id==='p18')return `<svg class="full-body iris-body" viewBox="200 0 650 1536" role="img" aria-label="${esc(a.name)}, personnage debout" preserveAspectRatio="xMidYMid meet"><image href="./assets/mercer-full.png" width="1024" height="1536"/></svg>`;if(a.id==='p17')return `<svg class="full-body iris-body" viewBox="200 0 650 1536" role="img" aria-label="${esc(a.name)}, personnage debout" preserveAspectRatio="xMidYMid meet"><image href="./assets/midnight-full.png" width="1024" height="1536"/></svg>`;if(a.id==='p16')return `<svg class="full-body iris-body" viewBox="0 0 600 1536" role="img" aria-label="${esc(a.name)}, personnage debout" preserveAspectRatio="xMidYMid meet"><image href="./assets/mira-dossier.png" width="1024" height="1536"/></svg>`;if(a.id==='p15')return `<svg class="full-body iris-body" viewBox="150 0 650 1536" role="img" aria-label="${esc(a.name)}, personnage debout" preserveAspectRatio="xMidYMid meet"><image href="./assets/apero-full.png" width="1024" height="1536"/></svg>`;if(['p0','p12','p13','p14'].includes(a.id))return `<svg class="full-body iris-body" viewBox="${a.id==='p14'?0:a.id==='p13'?10:a.id==='p12'?15:35} 0 650 1536" role="img" aria-label="${esc(a.name)}, personnage debout" preserveAspectRatio="xMidYMid meet"><image href="./assets/${a.id==='p14'?'lei':a.id==='p13'?'amber':a.id==='p12'?'bishop':'iris'}-full.png" width="1024" height="1536"/></svg>`;const i=a.portrait??0,col=i%6,row=Math.floor(i/6),y=row?524:0,h=row?500:524;return `<svg class="full-body" viewBox="${col*256} ${y} 256 ${h}" role="img" aria-label="${esc(a.name)}, personnage debout de la tête aux pieds" preserveAspectRatio="xMidYMid meet"><image href="./assets/agent-bodies.png?v=3" width="1536" height="1024"/></svg>`;}
